code.C:
#include <stdio.h>
#include <string.h>
int main() {
    char s[1000]; if (!fgets(s, sizeof(s), stdin)) return 0;
    int len = strlen(s);
    while (len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) s[--len] = '\0';
    for (int i = 0; i < len; i++) putchar('*');
    putchar('\n');
    return 0;
}

code.C++:
#include <iostream>
#include <string>
using namespace std;
int main() {
    string s; if (!getline(cin, s)) return 0;
    cout << string(s.length(), '*') << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            String s = sc.nextLine();
            System.out.println("*".repeat(s.length()));
        }
    }
}

